        if do_cols:
            for c in do_cols:
                print(f"  Intervention {c}: {df[c].unique()}")
    # Check for cloudiness/broth columns
    cloud_cols = [c for c in df.columns if 'loud' in c.lower() or 'turbid' in c.lower() or 'cloud' in c.lower()]
    if cloud_cols:
        for c in cloud_cols:
            print(f"  {c} mean: {df[c].mean():.3f}")

import pandas as pd
import numpy as np

# Load all experiments to analyze patterns
experiments = {}
for i in range(1, 8):
    fname = f'experiment_{i}_csv'
    try:
        df = pd.read_csv(eval(fname))
        experiments[i] = df
    except:
        pass

# Print summary of each experiment's key variables
print("=== EXPERIMENT SUMMARY ===")
for exp_id, df in experiments.items():
    cols = [c for c in df.columns if c in ['ProductTiter', 'FeedWaterFlowRate', 'DissolvedOxygen', 'ViableCellDensity', 'pH']]
    print(f"\nExp {exp_id}:")
    for c in cols:
        if c in df.columns:
            print(f"  {c}: mean={df[c].mean():.3f}, std={df[c].std():.3f}, n={len(df)}")

# Pool all data for correlation analysis
all_data = pd.concat(experiments.values(), ignore_index=True)
numeric_cols = all_data.select_dtypes(include=[np.number]).columns
print(f"\n=== POOLED CORRELATIONS WITH ProductTiter ===")
if 'ProductTiter' in numeric_cols:
    print(all_data[numeric_cols].corr()['ProductTiter'].round(3))

print(f"\n=== FLOW RATE vs TITER ===")
for exp_id, df in experiments.items():
    if 'FeedWaterFlowRate' in df.columns:
        flow_mean = df['FeedWaterFlowRate'].mean()
        titer_mean = df['ProductTiter'].mean() if 'ProductTiter' in df.columns else 'N/A'
        print(f"Exp {exp_id}: flow={flow_mean:.1f}, titer={titer_mean:.2f}")
